mapper.select:
select CALENDAR_ID id, CALENDAR_NAME text from MST_CALENDAR_INFO
and (CALENDAR_ID like concat(concat('%',#{search}),'%') or CALENDAR_NAME like concat(concat('%',#{search}),'%'))
and IS_TRADE_CALENDAR = #{isTradeCalendar}

select COUNTER_ID id, COUNTER_NAME text from MST_COUNTER_PARTY
and (COUNTER_ID like concat(concat('%',#{search}),'%') or COUNTER_NAME like concat(concat('%',#{search}),'%'))
and COUNTER_TYPE = #{counterType}

select CUSTOMER_ID id, CUSTOMER_NAME text from MST_CUSTOMER_INFO
and (CUSTOMER_ID like concat(concat('%',#{search}),'%') or CUSTOMER_NAME like concat(concat('%',#{search}),'%'))
and CUSTOMER_ID = #{initValue}
and IS_ISSUER = #{isIssuer}

SELECT T1.COUPON_SPECIES, T3.INT_TYPE FROM FIN_PRODUCT T1 LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID AND T3.EFF_DATE = T1.VDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

SELECT CUSTOMER_ID id, CUSTOMER_NAME text FROM MST_CUSTOMER_INFO
CUSTOMER_TYPE = #{CUSTOMER_TYPE_01,jdbcType=VARCHAR}
and ( CUSTOMER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR CUSTOMER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )

SELECT
count( * )
FROM
FIN_PRODUCT


		and FINPROD_MARKET_ID = #{finprodMarketId}


		and FINPROD_NAME = #{finprodName}

	AND FINPROD_TYPE2=#{F28}

SELECT
	INPUT_VALUE_1 inputValue1,
	INPUT_VALUE_2 inputValue2,
	INPUT_VALUE_3 inputValue3,
	INPUT_VALUE_4 inputValue4,
	INPUT_VALUE_5 inputValue5
FROM
    FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND OUTPUT_VALUE_1 = #{inputValue2}


    AND OUTPUT_VALUE_2 = #{inputValue3}


    AND OUTPUT_VALUE_3 = #{inputValue4}


    AND OUTPUT_VALUE_4 = #{inputValue5}

	select TYPE_6, TYPE_7, TYPE_8, IS_CREATE_PORTFOLIO
             from ASSET_TYPE_CONFIG


             		 and TYPE_6 = #{type_6}


             		 and TYPE_7 = #{type_7}


             		 and TYPE_8 = #{type_8}

SELECT
FINPROD_MARKET_ID code,
case FINPROD_TYPE2 when #{FINPROD_TYPE_TG_ZQ}
then FINPROD_ABBR
ELSE FINPROD_NAME
end name,
case FINPROD_TYPE2 when #{FINPROD_TYPE_TG_ZQ}
then  FINPROD_ABBR
ELSE FINPROD_NAME end shortName,
FINPROD_MARKET_ID hidCode
FROM FIN_PRODUCT

	FINPROD_TYPE2 in ('F01','F06','F10','F32')

		and (FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
		or FINPROD_ABBR like concat(concat('%',#{search}),'%')
		or FINPROD_NAME like concat(concat('%',#{search}),'%')
		)



		AND FINPROD_TYPE2 in

			#{item}



		AND P_FINPROD_ID IS NULL


		and PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}

SELECT ITEM_CODE id, ITEM_VALUE text, INSTITUTION_CODE institutionCode FROM SYS_DATADICT_LIST WHERE INSTITUTION_CODE IS NOT NULL
AND DICT_CODE = #{dictCode}
and institution_CODE IN ( SELECT INSTITUTION_CODE FROM SYS_INSTITUTION START WITH INSTITUTION_CODE = #{institution} CONNECT BY PRIOR INSTITUTION_CODE = UPPER_INSTITUTION_CODE )
UNION ALL SELECT ITEM_CODE id, ITEM_VALUE text, INSTITUTION_CODE institutionCode FROM SYS_DATADICT_LIST WHERE INSTITUTION_CODE IS NULL
AND DICT_CODE = #{dictCode}
AND NOT EXISTS ( SELECT 1 FROM SYS_datadict_list where institution_code = #{institution} )
